52	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
53	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
54	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
55	 * button behaviour.
56	 *
57	 * @param props see ZimmDrawerProps
58	 */
59	export const ZimmDrawer = (props: ZimmDrawerProps) => {
60	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
61	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
62	
63	  const title = 'title' in props ? props.title : undefined;
64	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
65	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
66	
67	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
68	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
69	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
70	  // reliable moment to restore focus. Covers both close-button click and Escape for all
71	  // consumers that pass finalFocusRef.
72	  const handleCloseComplete = () => {
73	    if (finalFocusRef) finalFocusRef.current?.focus();
74	  };
75	
76	  return (
77	    <Drawer isOpen={isOpen} onClose={onClose} placement="right" onCloseComplete={handleCloseComplete} initialFocusRef={initialFocusRef}>
78	      <DrawerOverlay sx={styles.overlay} />
79	      {/* Chakra's DrawerContent internally overrides aria-labelledby with its own headingId
80	          (undefined when DrawerHeader is not used), stripping the attribute. Use aria-label
81	          for the title case — Chakra does not override aria-label. */}
82	      <DrawerContent aria-labelledby={labelledBy} aria-label={title ?? ariaLabel} sx={styles.content}>
83	        {title ? (
84	          <chakra.div sx={styles.header}>
85	            <chakra.span
86	              sx={styles.headerTitle}
87	              textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
88	            >
89	              {title}
90	            </chakra.span>
91	            <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
92	          </chakra.div>
93	        ) : (
94	          <chakra.div sx={styles.closeButton}>
95	            <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
96	          </chakra.div>
97	        )}
98	        {children}
99	      </DrawerContent>
100	    </Drawer>
101	  );
102	};
