1	import { useEffect, useRef, useState } from 'react';
2	import type { RefObject, SyntheticEvent } from 'react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { useUiCopy } from 'app/hooks/useUiCopy';
5	import { useForm } from 'react-hook-form';
6	import type { UseFormReturn, FieldValues } from 'react-hook-form';
7	import { useDisclosure } from '@chakra-ui/react';
8	import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';
9	import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
10	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
11	import {
12	  getAuthorizePasswordlessErrorMessage,
13	  getLoginPasswordlessErrorMessage,
14	  getPasswordlessCallbackUrl,
15	} from '@salesforce/retail-react-app/app/utils/auth-utils';
16	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
17	import {
18	  setSessionJSONItem,
19	  getSessionJSONItem,
20	  clearSessionJSONItem,
21	  buildRedirectURI,
22	} from '@salesforce/retail-react-app/app/utils/utils';
23	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
